interface PricingStrategy {
  double apply(double base);
}

final class PremiumPricing implements PricingStrategy {
  public double apply(double base) { return base * 0.8; }
}

final class StandardPricing implements PricingStrategy {
  public double apply(double base) { return base; }
}

final class Checkout {
  private final PricingStrategy pricing;
  Checkout(PricingStrategy pricing) { this.pricing = pricing; }

  double total(double base) {
    return pricing.apply(base); // closed for modification, open for extension
  }
}
